const DEFAULT_BOOTSTRAP_RESAMPLES = 10_000;

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function quantile(values, probability) {
  const sorted = [...values].sort((a, b) => a - b);
  if (sorted.length === 0) return Number.NaN;
  const position = (sorted.length - 1) * probability;
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return sorted[lower];
  const weight = position - lower;
  return sorted[lower] * (1 - weight) + sorted[upper] * weight;
}

function median(values) {
  return quantile(values, 0.5);
}

function mean(values) {
  return values.length === 0 ? Number.NaN : values.reduce((sum, value) => sum + value, 0) / values.length;
}

function standardDeviation(values) {
  if (values.length < 2) return 0;
  const average = mean(values);
  return Math.sqrt(values.reduce((sum, value) => sum + (value - average) ** 2, 0) / (values.length - 1));
}

function pairedEffect(pairs, direction = 'higher-is-better') {
  const differences = pairs.map((pair) => pair.treatment - pair.baseline);
  const average = mean(differences);
  const effect = direction === 'higher-is-better' ? average : -average;
  const spread = standardDeviation(differences);
  const denominator = differences.length < 2 ? 0 : Math.sqrt(differences.length);
  const standardError = denominator === 0 ? 0 : spread / denominator;
  const dz = spread === 0 ? 0 : average / spread;
  return { differences, average, effect, standardError, dz };
}

function pairedTInterval(effect, standardError, confidence = 0.95) {
  // Normal approximation is deterministic and adequate for the preregistered fixture size.
  const z = confidence === 0.95 ? 1.959963984540054 : confidence === 0.90 ? 1.6448536269514722 : 1.959963984540054;
  const halfWidth = z * standardError;
  return [effect - halfWidth, effect + halfWidth];
}

function seedToRandom(seed) {
  let state = Number(seed) >>> 0;
  return () => {
    state += 0x6d2b79f5;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function bootstrapInterval(pairs, direction, resamples, seed, confidence) {
  const random = seedToRandom(seed);
  const effects = [];
  for (let sample = 0; sample < resamples; sample += 1) {
    const sampled = [];
    for (let index = 0; index < pairs.length; index += 1) {
      sampled.push(pairs[Math.floor(random() * pairs.length)]);
    }
    effects.push(pairedEffect(sampled, direction).effect);
  }
  const alpha = (1 - confidence) / 2;
  return [quantile(effects, alpha), quantile(effects, 1 - alpha)];
}

function sha256(value) {
  return createHash('sha256').update(value).digest('hex');
}

function stableJson(value) {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function normalizeCase(testCase, index) {
  assert(testCase && typeof testCase === 'object', `case ${index} must be an object`);
  assert(typeof testCase.id === 'string' && testCase.id.length > 0, `case ${index} requires id`);
  assert(Array.isArray(testCase.prompts), `case ${testCase.id} requires prompts`);
  assert(testCase.prompts.length > 0, `case ${testCase.id} requires at least one prompt`);
  return testCase;
}

function clone(value) {
  return structuredClone(value);
}

async function invoke(store, testCase, repetition) {
  const before = store.snapshot ? await store.snapshot() : store.getAll?.();
  const started = performance.now();
  let error;
  let response;
  try {
    for (const prompt of testCase.prompts) {
