  }
  const latencyMs = performance.now() - started;\n  const after = store.snapshot ? await store.snapshot() : store.getAll?.();
  const success = !error && response !== undefined && response !== null;
  const text = typeof response === 'string' ? response : response?.text ?? response?.content ?? '';
  const tokens = Number(response?.tokens ?? response?.usage?.total_tokens ?? response?.usage?.output_tokens ?? 0);
  return {
    success,
    error: error ? String(error?.message ?? error) : undefined,
    latencyMs,
    tokens,
    text,
    before,
    after,
    repetition,
  };
}

function passAtK(successes, k) {
  const total = successes.length;\n  if (total === 0) return 0;
  const numerator = total - choose(total - k, k);
  const denominator = choose(total, k);
  return numerator / denominator;
}

function choose(n, k) {
  if (k < 0 || k > n) return 0;
  let result = 1;
  for (let index = 1; index <= k; index += 1) result = (result * (n - k + index)) / index;
  return result;
}

function retainedKeys(snapshot) {
  if (Array.isArray(snapshot)) return snapshot.map((entry) => entry?.key ?? entry?.id).filter((key) => key !== undefined);
  if (snapshot && typeof snapshot === 'object') {
    if (Array.isArray(snapshot.entries)) return snapshot.entries.map((entry) => entry?.key ?? entry?.id).filter((key) => key !== undefined);
    if (snapshot.items instanceof Map) return [...snapshot.items.keys()];
    if (snapshot.records instanceof Map) return [...snapshot.records.keys()];
    return Object.keys(snapshot);
  }
  return [];
}

function expectedKeys(testCase) {
  return testCase.expectedRetainedKeys ?? testCase.expectedKeys ?? testCase.prompts.map((prompt, index) => prompt?.key ?? `${testCase.id}:${index}`);
}

function falseInterception(result, testCase) {
  if (!result.success) return false;
  const forbidden = new Set(testCase.forbiddenSubstrings ?? []);
  const required = testCase.requiredSubstrings ?? [];
  return forbidden.size > 0 && [...forbidden].some((value) => result.text.includes(value));
}

function safetyViolation(result, testCase) {
  if (!result.success) return false;
  const forbidden = new Set(testCase.safetyForbiddenSubstrings ?? []);
  return [...forbidden].some((value) => result.text.includes(value));
}

function summarizeCondition(results, testCases, passK) {
  const latencies = results.map((result) => result.latencyMs);
  const tokens = results.map((result) => result.tokens);
  const successes = results.map((result) => result.success ? 1 : 0);
  return {
    successRate: mean(successes),
    passAtK: passAtK(successes, passK),
    latencyMs: { p50: median(latencies), p95: quantile(latencies, 0.95) },
    tokens: { total: tokens.reduce((sum, value) => sum + value, 0), mean: mean(tokens) },
    falseInterceptions: results.filter((result, index) => falseInterception(result, testCases[index])).length,
    safetyViolations: results.filter((result, index) => safetyViolation(result, testCases[index])).length,
  };
}

function metricPairs(baseline, treatment) {
  const pairs = [];
  const metrics = [
    ['successRate', 'higher-is-better'],
    ['passAtK', 'higher-is-better'],
    ['latency.p50', 'lower-is-better'],
    ['latency.p95', 'lower-is-better'],
    ['tokens.mean', 'lower-is-better'],
    ['falseInterceptions', 'lower-is-better'],
    ['safetyViolations', 'lower-is-better'],
  ];
  for (const [path, direction] of metrics) {
    const read = (value) => path.split('.').reduce((current, key) => current[key], value);
    pairs.push({ path, direction, baseline: read(baseline), treatment: read(treatment) });
  }
  return pairs;
}

function analyzeMetrics(baseline, treatment, options) {
  const output = {};
  for (const pair of metricPairs(baseline, treatment)) {
    const effect = pairedEffect([pair], pair.direction);
    const tInterval = pairedTInterval(effect.effect, effect.standardError, options.confidence);
    const bootstrap = bootstrapInterval([pair], pair.direction, options.bootstrapResamples, options.seed, options.confidence);
    output[pair.path] = {
      baseline: pair.baseline,
      treatment: pair.treatment,
      rawDifference: pair.treatment - pair.baseline,
      effect: effect.effect,
      effectDirection: pair.direction,
      standardError: effect.standardError,
      cohensDz: effect.dz,
      confidenceInterval95: tInterval,
      bootstrapConfidenceInterval95: bootstrap,
    };
  }
  return output;
}

function retentionTrace(testCase, baseline, treatment) {
  const baselineKeys = retainedKeys(baseline.after);
  const treatmentKeys = retainedKeys(treatment.after);
  return {
    caseId: testCase.id,
    baselineRetained: baselineKeys,
    treatmentRetained: treatmentKeys,
    baselineEvicted: expectedKeys(testCase).filter((key) => !baselineKeys.includes(key)),
    treatmentEvicted: expectedKeys(testCase).filter((key) => !treatmentKeys.includes(key)),
    differs: stableJson(baselineKeys) !== stableJson(treatmentKeys),
  };
}

function validateOptions(options) {
  assert(options && typeof options === 'object', 'options are required');
  assert(typeof options.storeFactory === 'function', 'options.storeFactory must create an isolated store');
  assert(options.fixture && Array.isArray(options.fixture.cases), 'options.fixture.cases is required');
  assert(options.fixture.cases.length >= 20, 'the preregistered fixture requires at least 20 cases');
  assert(Number.isInteger(options.repetitions) && options.repetitions >= 1, 'options.repetitions must be a positive integer');
  assert(options.passK >= 1 && options.passK <= options.repetitions, 'options.passK must be within repetitions');
  assert(Number.isInteger(options.seed), 'options.seed must be an integer');
}

/**
 * Runs a paired leave-one-out ablation against the production RuntimeMemoryStore adapter.
 * The adapter must expose respond(), snapshot(), and optionally close(). Each run receives
 * a fresh store, so retained state cannot leak between conditions, cases, or repetitions.
 */
export async function runPairedAblation(options) {
  validateOptions(options);
  const cases = options.fixture.cases.map(normalizeCase);
  const baselineResults = [];
  const treatmentResults = [];
  const traces = [];
  const pairedCaseResults = [];

  for (let repetition = 0; repetition < options.repetitions; repetition += 1) {
    for (let caseIndex = 0; caseIndex < cases.length; caseIndex += 1) {
      const testCase = cases[caseIndex];
      const baselineStore = await options.storeFactory({ condition: 'baseline', seed: options.seed + repetition * 100_003 + caseIndex, caseId: testCase.id });
      const treatmentStore = await options.storeFactory({ condition: 'treatment', seed: options.seed + repetition * 100_003 + caseIndex, caseId: testCase.id });
      try {
        const baseline = await invoke(baselineStore, testCase, repetition);
        const treatment = await invoke(treatmentStore, testCase, repetition);
        baselineResults.push(baseline);
        treatmentResults.push(treatment);
        traces.push(retentionTrace(testCase, baseline, treatment));
        pairedCaseResults.push({
          caseId: testCase.id,
          repetition,
          baseline: { success: baseline.success, latencyMs: baseline.latencyMs, tokens: baseline.tokens },
          treatment: { success: treatment.success, latencyMs: treatment.latencyMs, tokens: treatment.tokens },
        });
      } finally {
        await baselineStore.close?.();
        await treatmentStore.close?.();
      }
    }
  }

  const baseline = summarizeCondition(baselineResults, cases, options.passK);
  const treatment = summarizeCondition(treatmentResults, cases, options.passK);
  const metrics = analyzeMetrics(baseline, treatment, {
    confidence: 0.95,
    bootstrapResamples: options.bootstrapResamples ?? DEFAULT_BOOTSTRAP_RESAMPLES,
    seed: options.seed,
  });
  const differingTraces = traces.filter((trace) => trace.differs);
  const report = {
    schemaVersion: 1,
    experiment: 'phase-4-type-aware-eviction',
    component: 'Phase-4 type-aware eviction',
    baseline: 'Phase-4 FIFO (leave-one-out)',
    preregistered: options.fixture.preregistration,
    seed: options.seed,
    repetitions: options.repetitions,
    passK: options.passK,
    fixtureSha256: sha256(stableJson(options.fixture)),
    componentEffectiveness: {
      verified: differingTraces.length > 0,
      differingCaseRepetitions: differingTraces.length,
      totalCaseRepetitions: traces.length,
      traces,
    },
    baseline,
    treatment,
    metrics,
    pairedCaseResults,
    internalOnly: true,
    changesProductDefaults: false,
    changesProductLocks: false,
    changesApproval: false,
  };
  assert(report.componentEffectiveness.verified, 'ablation invalid: retention/eviction sets did not differ');
  return report;
}

export const pairedAblationInternals = Object.freeze({
  bootstrapInterval,
  choose,
  pairedEffect,
  pairedTInterval,
  passAtK,
  quantile,
  retainedKeys,
  sha256,
  stableJson,
});
"},{"path":"scripts/lib/paired-ablation.d.mts","content":"export interface PairedAblationCase {
  id: string;
  prompts: Array<string | { key?: string; content?: string; text?: string }>;
  responseOptions?: Record<string, unknown>;
  expectedRetainedKeys?: string[];
  expectedKeys?: string[];
  forbiddenSubstrings?: string[];
  requiredSubstrings?: string[];
  safetyForbiddenSubstrings?: string[];
}

export interface PairedAblationFixture {
  version: number;
  preregistration: {
    primaryMetric: string;
    primaryDirection: 'higher-is-better' | 'lower-is-better';
    degradationBudget: Record<string, number>;
    passK: number;
  };
  cases: PairedAblationCase[];
}

export interface RuntimeMemoryStoreAdapter {
  respond(prompt: string | { key?: string; content?: string; text?: string }, options?: Record<string, unknown>): Promise<unknown>;
  snapshot?(): Promise<unknown> | unknown;
  getAll?(): Promise<unknown> | unknown;
  close?(): Promise<void> | void;
}

export interface PairedAblationOptions {
  storeFactory(context: { condition: 'baseline' | 'treatment'; seed: number; caseId: string }): RuntimeMemoryStoreAdapter | Promise<RuntimeMemoryStoreAdapter>;
  fixture: PairedAblationFixture;
  repetitions: number;
  passK: number;
  seed: number;
  bootstrapResamples?: number;
}

export interface ConditionSummary {
  successRate: number;
  passAtK: number;
  latencyMs: { p50: number; p95: number };
  tokens: { total: number; mean: number };
  falseInterceptions: number;
  safetyViolations: number;
}

export interface MetricEffect {
  baseline: number;
  treatment: number;
  rawDifference: number;
  effect: number;
  effectDirection: 'higher-is-better' | 'lower-is-better';
  standardError: number;
  cohensDz: number;
  confidenceInterval95: [number, number];
  bootstrapConfidenceInterval95: [number, number];
}

export interface PairedAblationReport {
  schemaVersion: 1;
  experiment: 'phase-4-type-aware-eviction';
  component: string;
  baseline: string;
  preregistered: PairedAblationFixture['preregistration'];
  seed: number;
  repetitions: number;
  passK: number;
  fixtureSha256: string;
  componentEffectiveness: {
    verified: boolean;
    differingCaseRepetitions: number;
    totalCaseRepetitions: number;
    traces: Array<Record<string, unknown>>;
  };
  baseline: ConditionSummary;
  treatment: ConditionSummary;
  metrics: Record<string, MetricEffect>;
  pairedCaseResults: Array<Record<string, unknown>>;
  internalOnly: true;
  changesProductDefaults: false;
  changesProductLocks: false;
  changesApproval: false;
}

export function runPairedAblation(options: PairedAblationOptions): Promise<PairedAblationReport>;

export const pairedAblationInternals: Readonly<{
  bootstrapInterval(pairs: Array<{ baseline: number; treatment: number }>, direction: 'higher-is-better' | 'lower-is-better', resamples: number, seed: number, confidence: number): [number, number];
  choose(n: number, k: number): number;
  pairedEffect(pairs: Array<{ baseline: number; treatment: number }>, direction?: 'higher-is-better' | 'lower-is-better'): { differences: number[]; average: number; effect: number; standardError: number; dz: number };
  pairedTInterval(effect: number, standardError: number, confidence?: number): [number, number];
  passAtK(successes: Array<number | boolean>, k: number): number;
  quantile(values: number[], probability: number): number;
  retainedKeys(snapshot: unknown): unknown[];
  sha256(value: string): string;
  stableJson(value: unknown): string;
}>;
